import base64,io
from PIL import Image
def th(n):
    im=Image.open('audit_shots/'+n+'.png').convert('RGB');im=im.resize((180,376));b=io.BytesIO();im.save(b,'JPEG',quality=70);return 'data:image/jpeg;base64,'+base64.b64encode(b.getvalue()).decode()
V=[('Lo-fi','onb_sms','Figma lo-fi; SMS rationale screen','Every feature on paper; funds, pre-pay widget','SMS premise; grey forms; 5 numbers on Home','SMS dropped → UPI link or manual'),
('v2 · dark A–C','v2_home','5 tabs, text stats, 8 text insight cards','Shared seeded store; friction sheet at pay','Reads like a form; balance + weekly + daily on Home','"Text-heavy" → visual system'),
('Explorations','expl2_first','6 IA concepts: Envelope, Pulse, Ledger…','Wide range; Pulse single hero','Separate apps; notification-access copy','Copy dropped; pace idea kept'),
('Visual redesign','redesign_home','A metaphor per screen','First visual attempt; emotional goal climb','Road, mountain, iceberg: nothing learnable','"Too many one-off metaphors"'),
('v3','v3_home','Dark stat cards, 5 reusable components','Small repeated vocabulary','Still numbers-first (triad + balance)','"Push everything to be visual"'),
('v4','v4_home','Sparklines, projections, MoM','Real comparisons, goal projection','Density up, nothing removed','More visual asked'),
('v5','v5_ins','17 chart forms, 16 cards','Fit/no-fit plan per chart','Radar, bubble, scatter; chart library','Audit: duplicates, bugs'),
('v6','v6_home','Every frame visual, ~45 charts','Tooltips, palette, rich seed','Red status; radial arcs mislead','Income/pools needed'),
('v7','v7_home','Pools, 44 widgets, inbox, covers','Real money model + ledger invariant','Home 75 numbers, red carry, badge "5 things"','"Too much info; panic on open"'),
('v8','v8_home','Calm: glow pace, tiles, one choice/step','No budget on Home; pay tiles leave; auto split','3 tile units, mostly unlabelled; 120-tile grids','Units unclear'),
('v9','v9_ins','Adaptive tile ladder, 20 widgets, Sankey, sound','Key on every card; repeat buys; B&W','Tile worth changes per card; breadth again','Still hard to read'),
('v10','v10_home','6-shape denominations ₹10–₹5,000','Clean glyph craft, logo, splash','Memorise ladder; mental arithmetic; slow','"Shapes are not working"')]
cards=''.join(f'<article class="v"><img src="{th(s)}" alt="{n} screenshot" loading="lazy"><div><h3>{n}</h3><p class="c">{c}</p><p><b class="g">+</b> {g}</p><p><b class="r">−</b> {w}</p><p class="x">→ {x}</p></div></article>' for n,s,c,g,w,x in V)
keep=[('No budget number on Home; pace as glow + word','v8'),('One decision per screen, default preselected','v8'),('Pay: payment tiles leave the category','v8/v9'),('Income auto-split, one confirm + undo','v8'),('Money = Income · Budget · Savings accordion','v8'),('Goal waffle with head start','v8'),('Repeat buys + "3rd time here" line at pay','v9'),('Weekly check-in + story ending "You saved ₹X"','v8/v9'),('Key on every visual, exact ₹ on tap','v9'),('Ledger invariant validator','v7'),('Subscriptions as fixed chunk with due ring','v3/v9'),('Plain-language glossary','v8'),('Soft sound, reduced motion, B&W with pattern','v9'),('"Friends owe you", outside balance','v7/v8')]
drop=['Adaptive unit ladder','Shape denominations, mixed piles, breaking change','Sankey as a main view (Insights deep view at most)','20-widget default board (≤3 visible + library)','Range, 24h ring, weekday, size widgets by default','Inbox of many action cards','Leftover Auto/Manual choice','Balance as Money headline','Allocation pie + sliders in onboarding','30-tile period strip']
never=['More than one tile unit, or a unit that changes by card','Shape or denomination systems to memorise','A new metaphor per screen','Budget, safe-to-spend or balance on Home','Red deficits and debt words','More than 2 numbers on first view; stat triads','Badge counts, "N things need you"','Multi-slider allocation, multi-option cover sheets','Radar, bubble, scatter, radial arcs','Streaks, points, badges','SMS or notification scraping','Accounting jargon in UI (To assign, pools, sweep)']
crit=[('Tile value understood','≤ 5 s','≥80% of new users'),('Which is more','≤ 3 s','≥90% correct'),('Budget set','≤ 30 s','≤4 taps with defaults'),('Decisions per screen','1','one choice group'),('Budget numbers on Home','0','pace in words'),('Numbers on load','≤ 2','keys excluded'),('Tile units app-wide','1','one key, taught once'),('Pay to UPI hand-off','≤ 3 steps','tiles leave ≤1.2 s'),('Income sorted','1 tap','with undo'),('Return triggers','day 2 · 7 · 30','glance · check-in · story'),('Red on Home/Pay/Savings','0','no debt words'),('Ledger checks','100%','after every flow')]
roots=['Every fix added a new thing to learn: chart forms, widgets, tile units, shapes.','Unit instability: a tile meant ₹100, ₹500, 1%, a count, ₹10–2,500, then six shapes.','Numbers-first defaults on Home caused anxiety and avoidance.','Decision load: sliders, cover sheets, inbox, sweeps, widget curation.','Breadth over depth: 44 → 20 widgets while the core loop got less polish.','Alarm and debt framing: red, "carried", "over".','System language over student language: pools, To assign, breaking change.']
li=lambda a:''.join(f'<li>{x}</li>' for x in a)
html=open('tpl.html').read().replace('%CARDS%',cards).replace('%KEEP%',''.join(f'<li>{a} <span class="t">{b}</span></li>' for a,b in keep)).replace('%DROP%',li(drop)).replace('%NEVER%',li(never)).replace('%ROOTS%',li(roots)).replace('%CRIT%',''.join(f'<div class="k"><span class="kv">{b}</span><span class="kl">{a}</span><span class="kn">{c}</span></div>' for a,b,c in crit))
open('trickle-v11-audit.html','w').write(html);print(len(html))
